installer-gui-script.script:
function installCheck() {
  if (system.sysctl('hw.optional.arm64') != 1) {
    my.result.title = 'ScopeCreep needs Apple Silicon';
    my.result.message = 'This Mac has an Intel processor. ScopeCreep runs only on Apple Silicon Macs (M1 or later), so it was not installed.';
    my.result.type = 'Fatal';
    return false;
  }
  return true;
}
